from concurrent.futures import ThreadPoolExecutor, as_completed

N, R, W = 3, 2, 2            # Dynamo's common setting: R + W > N

def descends(a: dict, b: dict) -> bool:
    """Vector clock a has seen every event that b has."""
    return all(a.get(node, 0) >= n for node, n in b.items())

def reconcile(versions: list[tuple[dict, bytes]]) -> list[tuple[dict, bytes]]:
    # Drop versions that another version descends from; the rest are siblings
    uniq = list({tuple(sorted(c.items())): (c, v) for c, v in versions}.values())
    return [(c, v) for c, v in uniq
            if not any(o != c and descends(o, c) for o, _ in uniq)]

def put(key, value, clock: dict, ring, pool: ThreadPoolExecutor) -> dict:
    replicas = ring.preference_list(key, N)       # first N healthy nodes clockwise
    clock = {**clock, ring.me: clock.get(ring.me, 0) + 1}
    futures = [pool.submit(r.write, key, value, clock) for r in replicas]
    acks = 0
    for f in as_completed(futures, timeout=0.3):
        acks += f.result() is True
        if acks >= W:
            return clock                          # stragglers finish in the background
    raise TimeoutError("write quorum not reached")

def get(key, ring, pool: ThreadPoolExecutor) -> list[tuple[dict, bytes]]:
    futures = [pool.submit(r.read, key) for r in ring.preference_list(key, N)]
    replies = [f.result() for _, f in zip(range(R), as_completed(futures, timeout=0.3))]
    return reconcile([v for reply in replies for v in reply])  # >1 = siblings to merge
